styl:
.bb { border-bottom: 1px solid #d9d9db; }
.h-24 { font-size: 8px;
  line-height: 24px;
  height: 24px; }
.left-block { display: inline-block;
  width: 49%;
  vertical-align: top; }
@media screen and (max-width: 600px) {
  .left-block { float: none !important;
    display: block !important;
    width: 100% !important; }
}
.right-block { display: inline-block;
  width: 49%;
  vertical-align: top;
  text-align: right; }
@media screen and (max-width: 600px) {
  .right-block { float: none !important;
    display: block !important;
    width: 100% !important;
    padding-top: 12px !important; }
}
.small-title { font-family: Helvetica !important;
  font-style: normal;
  font-weight: 700;
  font-size: 24px;
  line-height: 31px;
  color: #393a44; }
@media screen and (max-width: 600px) {
  .small-title { font-size: 21px !important;
    line-height: 29px !important; }
}
.asset-logo { display: inline-block;
  width: 56px !important;
  float: none;
  vertical-align: middle;
  padding-right: 16px; }
.small-number { font-family: Helvetica !important;
  font-style: normal;
  font-weight: 700;
  font-size: 18px;
  line-height: 27px;
  color: #393a44; }
.small-green-number { font-family: Helvetica !important;
  font-style: normal;
  font-weight: 700;
  font-size: 18px;
  line-height: 27px;
  color: #12a557; }
.left-number { display: inline-block;
  width: 60px;
  vertical-align: middle; }
@media screen and (max-width: 600px) {
  .left-number { width: 100px !important;
    text-align: center !important; }
}
.small-arrow { display: inline-block;
  width: 27px !important;
  vertical-align: middle;
  float: none;
  padding: 0 15px; }
.right-number { display: inline-block;
  width: 60px;
  vertical-align: middle; }
@media screen and (max-width: 600px) {
  .right-number { width: 100px !important;
    text-align: center !important; }
}
@media screen and (max-width: 600px) {
  .text-center-mob { text-align: center !important;
    margin: 0 auto !important; }
}
.big-green-number { font-family: Helvetica !important;
  font-style: normal;
  font-weight: 700;
  font-size: 24px;
  line-height: 31px;
  text-align: right;
  color: #12a557; }
@media screen and (max-width: 600px) {
  .big-green-number { text-align: center !important; }
}
.asset-logo { display: inline-block;
  width: 40px !important;
  float: none;
  padding-right: 8px;
  vertical-align: middle; }
.small-gray-text { font-family: Helvetica !important;
  font-style: normal;
  font-weight: 400;
  font-size: 16px;
  line-height: 24px;
  color: #84868b; }
.gray-block { padding: 24px;
  background: #f9f9f9;
  border-radius: 12px; }
